-- ============================================================================
-- PARTIE 33 — Version e-learning du module 2 : thème et séquence 1/3 (Apport)
-- Source : projet pédagogique Koala Kids (partie 3 : réponse aux besoins affectifs,
-- tempêtes émotionnelles, postures « port d'attache » et « boussole », violences
-- éducatives ordinaires) et séance animée 1/3 du module 2.
-- Crée un second thème, en parallèle de la séance animée de 45 min, avec une séquence
-- en lecture seule d'environ 30 minutes : 29 blocs (10 texte, 7 question, 3 dialogue, 3 reflexion, 1 citation, 1 comparaison, 1 discussion, 1 essayer, 1 retenir, 1 scenes),
-- dont 7 questions avec correction, 3 mises en situation, 3 temps de réflexion et un bloc « Échange ».
-- LA SÉQUENCE RESTE EN BROUILLON (publie = false).
-- Prérequis : parties 25 (types « question » et « dialogue ») et 30 (type « discussion »)
-- exécutées. Aucune image dans cette version.
-- À exécuter en 3 temps : 33.1, 33.2, puis 33c.
-- Relançable : le thème et la séquence ne sont créés qu'une fois, et les blocs
-- ne sont ajoutés que si la séquence n'en contient aucun.
-- Les prénoms (Mia, Rayan, Nina, Malo) sont fictifs : ce ne sont pas des enfants du site.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 33.1 Thème et séquence. Attendu : aucune ligne retournée.
-- ---------------------------------------------------------------------------
do $do$
declare tid public.theme.id%type;
begin
  select id into tid from public.theme where nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$;
  if tid is null then
    insert into public.theme(nom, description, ordre, programme)
    values ($kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$,
            $kk$Version e-learning du module 2, à suivre à son rythme : lecture, situations vécues, questions avec correction et mises en situation. 3 séquences d'environ 30 minutes. Complète les microséquences animées de 45 min.$kk$,
            2, 'Programme de formation (Modules 1 à 10)')
    returning id into tid;
  end if;

  if not exists (select 1 from public.module where theme_id = tid and titre = $kk$Module 2 – 1/3 · Apport (e-learning)$kk$) then
    insert into public.module(theme_id, titre, accroche, publie, ordre, trame)
    values (tid, $kk$Module 2 – 1/3 · Apport (e-learning)$kk$,
            $kk$Mia, 10 mois, se réveille de la sieste en pleurant. Rien n'explique ses larmes. **Que dit ce pleur, et que faire avant de chercher à le faire cesser ?**$kk$,
            false, 0, null);
  end if;
end
$do$;
-- FIN 33.1

-- ---------------------------------------------------------------------------
-- 33.2 Blocs de la séquence. Attendu : aucune ligne retournée (blocs ajoutés une seule fois).
-- ---------------------------------------------------------------------------
do $do$
declare mid public.module.id%type;
begin
  select m.id into mid from public.module m join public.theme t on t.id = m.theme_id
  where t.nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$ and m.titre = $kk$Module 2 – 1/3 · Apport (e-learning)$kk$;
  if mid is null then raise notice '33.2 : séquence introuvable, exécuter 33.1'; return; end if;
  if exists (select 1 from public.bloc where module_id = mid) then raise notice '33.2 : déjà exécuté'; return; end if;

  insert into public.bloc(module_id, type, contenu, ordre)
  select mid, v.type, v.contenu, v.ordre
  from (values
  ('texte', $kk${"titre": "Ce que vous allez faire", "paragraphes": ["Cette séquence est la version à suivre **à votre rythme** de la première séance du module 2. Comptez **environ 30 minutes**, en une fois ou en deux temps : vous pouvez vous arrêter et reprendre quand vous le souhaitez.", "Vous y trouverez des situations vécues, **sept questions avec correction**, **trois mises en situation** et **trois temps de réflexion**. Les questions ne sont pas notées. Ce que vous écrivez reste sur votre appareil.", "À la fin, vous saurez dire ce que peut exprimer un pleur et répondre d'abord en **port d'attache** (sécuriser), puis en **boussole** (nommer l'émotion et soutenir l'enfant), sans chercher à la faire cesser."]}$kk$::jsonb, 0),
  ('reflexion', $kk${"question": "Pensez à un pleur ou à une colère de cette semaine, sans le raconter en détail. Qu'est-ce que l'enfant disait, selon vous ? Qu'avez-vous fait en premier ?", "sous_titre": "Il s'agit de décrire, pas de juger. Il n'y a pas de bonne réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 1),
  ('texte', $kk${"titre": "Un pleur est un message", "paragraphes": ["Quand quelque chose ne va pas pour lui, le jeune enfant **manifeste son mal-être en pleurant**. Ses pleurs sont en quelque sorte **un système d'alarme**.", "Il se trouve alors dans un état émotionnel qu'il est incapable de contrôler seul, et il a besoin de l'adulte pour s'apaiser. Quand l'adulte répond et cherche à régler la cause de son chaos, l'enfant se calme. Il apprend ainsi peu à peu qu'il peut **compter sur cette personne** quand il éprouve un malheur.", "Le repère de cette séquence est simple : **avant de chercher à faire cesser un pleur, on cherche ce qu'il dit**. Fatigue, faim, besoin de lien, émotion trop grosse : un pleur dit un besoin."]}$kk$::jsonb, 2),
  ('texte', $kk${"titre": "Ni exagération, ni caprice, ni manipulation", "paragraphes": ["Un jeune enfant **ne fait pas de « bêtises »** et **ne cherche pas à « embêter » les adultes** : il découvre un environnement dont il ne connaît pas encore le mode d'emploi. Son cerveau encore immature ne lui permet pas de comprendre le monde comme nous.", "Comprendre cette immaturité évite **le piège de l'interprétation** (« il le fait exprès, il me provoque »). Les émotions d'un enfant disent ce qu'il vit et ressent **ici et maintenant** : elles sont toujours vraies, authentiques et dignes d'être exprimées. Ce ne sont ni des exagérations, ni des volontés de nuire ou de manipuler."]}$kk$::jsonb, 3),
  ('scenes', $kk${"titre": "Trois pleurs, trois lectures", "items": [{"lettre": "A", "titre": "Elle pleure au réveil, sans cause visible", "texte": "Mia, 10 mois, se réveille de la sieste en pleurant fort. Elle n'a pas faim, sa couche est propre. Une collègue dit : « Elle réclame, laisse-la un peu. »", "analyse": "un pleur sans cause apparente reste un message. L'enfant ne peut pas apaiser seul ce qu'il ressent, et **tarder à répondre** ne lui permet pas de s'apaiser. On s'approche, on la prend dans les bras au besoin, on cherche ce dont elle a besoin : sommeil, lien, faim, émotion."}, {"lettre": "B", "titre": "Il hurle, tape et cherche à mordre", "texte": "On vient de reprendre un objet dangereux à Rayan, 22 mois. Il se jette par terre, hurle, tape du poing, puis cherche à mordre l'adulte qui se penche vers lui.", "analyse": "entre 1 et 3 ans, les enfants connaissent de véritables **tempêtes émotionnelles** : ils tapent, mordent, peuvent éprouver de vraies paniques, sans comprendre ce qui se passe ni pouvoir s'apaiser seuls. Il ne cherche pas à nuire. On reste près de lui, on le protège et on protège les autres, on ne le laisse pas seul avec sa détresse."}, {"lettre": "C", "titre": "Elle ne pleure pas, mais quelque chose ne va pas", "texte": "Nina, 16 mois, ne pleure pas. Dès qu'un bruit éclate, elle se raidit. Quand on s'approche, elle recule d'un pas, puis finit par s'asseoir seule dans un coin, le regard baissé.", "analyse": "une émotion ne passe pas toujours par les larmes. Gestuelle, regard, mimiques, crispation, mouvement de recul, position de retrait : **le corps parle autant que les mots**. On s'approche doucement, on observe, on met des mots sur ce qu'on voit."}]}$kk$::jsonb, 4),
  ('question', $kk${"enonce": "Mia pleure à son réveil sans cause apparente. Que **traduit** le plus justement son pleur ?", "options": [{"texte": "Un caprice : elle réclame de l'attention", "juste": false}, {"texte": "Un signal d'alarme : elle ne peut pas apaiser seule ce qu'elle ressent et a besoin de l'adulte", "juste": true}, {"texte": "Une habitude qu'il ne faut pas encourager en répondant", "juste": false}], "explication": "Le pleur est un **système d'alarme** : l'enfant est dans un état émotionnel qu'il ne peut pas contrôler seul. Ce n'est ni un caprice, ni une exagération, ni une volonté de manipuler. Avant de chercher à le faire cesser, on cherche **ce qu'il dit**."}$kk$::jsonb, 5),
  ('texte', $kk${"titre": "Lire le corps autant que les mots", "paragraphes": ["Les pleurs ne sont pas le seul langage des émotions. Soyez attentive aux **manifestations corporelles** : gestuelle, regards, mimiques, crispation, mouvement de recul, position de retrait, autant qu'aux paroles.", "Cela demande d'être disponible, et de **prendre du recul** pour ne pas confondre vos propres ressentis avec les siens : un jeune enfant est un autre, il ne pense pas le monde comme les adultes. Les enfants lisent d'ailleurs plus facilement les expressions des visages que les mots : ils ont besoin de bien voir votre visage, et surtout vos yeux."]}$kk$::jsonb, 6),
  ('question', $kk${"enonce": "Nina ne pleure pas, mais se raidit, recule et se retire dans un coin. Que faire en premier ?", "options": [{"texte": "S'approcher doucement, observer, mettre des mots sur ce qu'on voit et rester disponible", "juste": true}, {"texte": "Rien : elle ne pleure pas, donc elle va bien", "juste": false}, {"texte": "Lui demander de sourire pour la rassurer", "juste": false}], "explication": "L'absence de larmes ne dit pas l'absence d'émotion. On **observe** le corps, on s'approche sans forcer, on **nomme** ce qu'on voit (« tu as eu peur du bruit ») et on reste disponible."}$kk$::jsonb, 7),
  ('texte', $kk${"titre": "Répondre, sans anticiper ni tarder", "paragraphes": ["Il est primordial de **répondre aux signaux des enfants de façon chaleureuse et régulière** : les prendre dans les bras, les consoler quand ils pleurent, chercher à apaiser la cause de leur malheur. Ils comprennent ainsi qu'ils peuvent **compter sur les adultes** quand quelque chose ne va pas.", "Deux écueils. **Répondre avant** qu'ils expriment leur besoin ne leur permet pas cette compréhension ; **tarder à répondre** ne leur permet pas de s'apaiser ni d'apprendre à se sécuriser. Quant à l'absence de réaction, c'est une situation très angoissante : les jeunes enfants s'y sentent perdus et abandonnés.", "Répondre à une demande d'affection, c'est dire à l'enfant : « **je te vois, je t'entends, tu as raison de faire appel à moi, et je suis là pour toi** ». C'est lui dire qu'il existe pour nous, individuellement, dans ce collectif d'enfants, et que sa demande est légitime."]}$kk$::jsonb, 8),
  ('question', $kk${"enonce": "Un enfant pleure depuis un moment, et vous êtes occupée avec un autre. Quelle règle guide le mieux votre réponse ?", "options": [{"texte": "Attendre qu'il se calme seul, pour qu'il apprenne à se débrouiller", "juste": false}, {"texte": "Intervenir avant qu'il pleure, pour lui éviter toute frustration", "juste": false}, {"texte": "Répondre à son signal de façon chaleureuse, sans trop tarder, mais sans anticiper à sa place", "juste": true}], "explication": "Il faut éviter les deux écueils : **tarder** ne permet pas à l'enfant de s'apaiser, et **répondre avant** qu'il exprime son besoin ne lui permet pas de comprendre qu'il peut compter sur l'adulte quand il appelle."}$kk$::jsonb, 9),
  ('texte', $kk${"titre": "Ne pas laisser un enfant seul au milieu de sa tempête", "paragraphes": ["L'immaturité cérébrale des jeunes enfants ne leur permet pas de contrôler leurs émotions. **Entre 1 et 3 ans**, ils connaissent de véritables **tempêtes émotionnelles**, sans comprendre ce qui se passe et sans pouvoir les apaiser seuls : ils tapent, mordent et peuvent éprouver de véritables paniques.", "Selon le projet pédagogique, les laisser seuls face à cette profonde détresse revient à les **abandonner au beau milieu de la mer, sans aucun abri où trouver refuge**. C'est particulièrement délétère pour leur cerveau, envahi par la sécrétion de cortisol, et cela peut entraver leur développement ainsi que leurs apprentissages.", "C'est pourquoi on **ne punit pas et on n'isole pas** : toute violence physique ou verbale et tout isolement d'un enfant sont des fautes professionnelles. La séquence suivante y revient."]}$kk$::jsonb, 10),
  ('reflexion', $kk${"question": "Face à un enfant qui tape ou mord dans une tempête, quel est votre premier réflexe ? Et que se passe-t-il dans votre corps à ce moment-là ?", "sous_titre": "Repérer son propre réflexe aide à répondre autrement. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 11),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "« Elle pleure pour attirer l'attention »", "contexte": "10 h 15. Une enfant pleure depuis quelques minutes près des étagères. Une collègue passe, jette un œil et continue son chemin.", "repliques": [{"qui": "Votre collègue", "texte": "Laisse, elle pleure pour qu'on s'occupe d'elle. Si on y va à chaque fois, elle va recommencer."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Je sais que la matinée est longue. Mais un pleur est un signal : elle ne peut pas calmer seule ce qu'elle ressent. Si elle cherche notre attention, c'est qu'elle en a besoin. Je vais m'asseoir près d'elle, la consoler et nommer ce qu'elle vit. Si tu veux, on se relaie.", "points": ["Reconnaître la fatigue de la collègue, sans la juger.", "Rappeler que le pleur est un signal d'alarme, pas une manipulation.", "Agir plutôt que débattre : aller consoler l'enfant.", "Proposer de se relayer : on analyse des pratiques, pas des personnes."]}$kk$::jsonb, 12),
  ('texte', $kk${"titre": "Port d'attache, boussole", "paragraphes": ["Deux postures guident votre réponse, dans cet ordre. (Une troisième, le **phare**, qui étaye le jeu de l'enfant, complète la fiche « Trois postures » : cette séquence insiste sur les deux premières.)", "**Le port d'attache.** L'adulte est **visible, disponible et facile à rejoindre**. Il répond, console, reste près de l'enfant, qui se calme et apprend qu'il peut compter sur lui. Ses mots : « **Je te vois et tu comptes pour moi.** »", "**La boussole.** Quand une émotion submerge l'enfant, l'adulte se place à ses côtés : il **nomme l'émotion, la reconnaît comme légitime**, soutient l'enfant pour l'apprivoiser plutôt que de la faire cesser, et lui indique la direction du réconfort. Ses mots : « **Je comprends qui tu es et tu peux compter sur moi.** »"]}$kk$::jsonb, 13),
  ('citation', $kk${"texte": "« Ce n'est pas tant cela qui fatigue le plus que le fait d'être obligés de nous élever jusqu'à la hauteur de leurs sentiments. De nous élever, nous étirer, nous mettre sur la pointe des pieds, nous tendre, pour ne pas les blesser. »\nJanusz Korczak, Quand je redeviendrai petit"}$kk$::jsonb, 14),
  ('question', $kk${"enonce": "Face à un enfant en pleine tempête, lesquels de ces gestes relèvent du port d'attache ? (plusieurs réponses)", "options": [{"texte": "Rester près de lui, disponible et visible", "juste": true}, {"texte": "L'envoyer seul dans un coin calme jusqu'à ce qu'il se calme", "juste": false}, {"texte": "Le prendre dans les bras et le consoler au besoin", "juste": true}, {"texte": "Chercher à apaiser la cause de sa détresse", "juste": true}], "explication": "Le port d'attache, c'est **rester**, **consoler** et chercher la cause. Envoyer un enfant seul dans un coin, c'est l'isoler : il reste alors seul avec une détresse qu'il ne peut pas apaiser, et c'est une faute professionnelle."}$kk$::jsonb, 15),
  ('comparaison', $kk${"intro": "**Face à un pleur, quelques repères.**", "plutot": ["**Se mettre à sa hauteur**, le regarder, rester près de lui.", "**Nommer** ce qu'il vit : « Tu es triste de quitter maman ce matin, je comprends. »", "**Consoler** : le prendre dans les bras, le bercer, lui chanter une comptine ou lui raconter une histoire.", "**Chercher la cause** (fatigue, faim, besoin de lien, émotion trop grosse) et la régler si l'on peut."], "eviter": ["**Nier** : « Ce n'est rien, tu n'as pas de raison de pleurer. »", "**Interpréter** : « Il le fait exprès, il me provoque. »", "**Le laisser seul** avec sa tempête, ou **l'isoler** pour qu'il se calme.", "**Tout régler avec un objet** : tendre le doudou à chaque chagrin, à la place de l'adulte."]}$kk$::jsonb, 16),
  ('question', $kk${"enonce": "Un enfant pleure et on lui tend aussitôt son doudou, à chaque fois. Que penser de cette pratique ?", "options": [{"texte": "Le doudou est obligatoire pour être accueilli à la crèche", "juste": false}, {"texte": "Il faut retirer le doudou pour que l'enfant apprenne à compter sur l'adulte", "juste": false}, {"texte": "Il peut aider, mais proposé systématiquement à tout chagrin il remplace l'adulte, qui reste la figure d'attachement nécessaire", "juste": true}], "explication": "Le doudou est une **aide symbolique** qui permet à l'enfant de se rassurer, mais il n'est en aucun cas obligatoire. Proposé systématiquement, il ne joue plus son rôle : l'adulte, par ses bras, ses mots et son empathie, reste le meilleur moyen de s'apaiser. Un enfant qui a un chagrin doit pouvoir compter sur ses figures d'attachement pour **reconnaître son chagrin comme légitime**. On ne retire pas pour autant le doudou : on le respecte."}$kk$::jsonb, 17),
  ('texte', $kk${"titre": "Se mettre à sa hauteur, nommer", "paragraphes": ["Nommer ce que vit l'enfant lui permet de **comprendre peu à peu ce qu'il vit et ressent**. C'est aussi **accepter son émotion comme légitime**, ce qui la rend acceptable pour lui : « Tu es triste de quitter maman ce matin, je comprends. » ou « Tu es très content de partir en balade, tu as raison. »", "Il ne s'agit pas de faire cesser l'émotion : on offre **nos mots, notre empathie, notre tendresse** pour consoler et, éventuellement, une alternative avec un choix possible pour sortir de la frustration. Vous développerez cette posture dans la séquence 3."]}$kk$::jsonb, 18),
  ('question', $kk${"enonce": "Parmi ces phrases adressées à un enfant qui pleure, laquelle reconnaît son émotion comme légitime ?", "options": [{"texte": "« Ne t'inquiète pas, ça va passer. »", "juste": false}, {"texte": "« Regarde, il y a un camion ! »", "juste": false}, {"texte": "« Tu es triste, je comprends. Je suis là. »", "juste": true}], "explication": "Les deux premières phrases **nient** l'émotion ou **détournent** l'attention. La troisième la **nomme**, la reconnaît comme légitime et dit que l'adulte reste disponible : c'est la posture de la boussole."}$kk$::jsonb, 19),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Un parent veut qu'on le laisse pleurer", "contexte": "17 h 20. Le papa de Malo, 18 mois, vous parle à voix basse en enfilant le manteau de son fils.", "repliques": [{"qui": "Le papa de Malo", "texte": "À la maison, je le laisse pleurer dans sa chambre : il faut qu'il apprenne à se calmer seul. J'espère que vous faites pareil ici."}], "consigne": "Que répondez-vous à ce parent ?", "reponse_modele": "Je vois que vous voulez l'aider à devenir autonome. À son âge, Malo ne peut pas encore apaiser seul une émotion trop grosse : il a besoin d'un adulte pour y arriver. Ici, quand il pleure, je reste près de lui, je nomme ce qu'il vit et je le console. Si vous le souhaitez, je vous raconte comment ça se passe.", "points": ["Reconnaître l'intention du parent, sans le juger ni le dévaloriser.", "Expliquer : à cet âge, l'enfant ne peut pas apaiser seul une émotion trop grosse.", "Dire simplement ce que l'on fait ici : rester près, nommer, consoler.", "Proposer d'en reparler, plutôt que de corriger."]}$kk$::jsonb, 20),
  ('texte', $kk${"titre": "Et vous, dans tout ça ?", "paragraphes": ["Accueillir les émotions des enfants demande de **maîtriser les siennes** : c'est ce qui permet de se laisser toucher par celles des enfants, **sans craindre de les mésinterpréter, de les nier ou de les enflammer**.", "Cela n'empêche pas d'être débordée. **Avant d'arriver à la faute**, trois choses sont indispensables pour continuer à éduquer et à soutenir l'enfant de façon adaptée : **parler de ses propres émotions**, **demander de l'aide quand on n'en peut plus**, **analyser les difficultés en équipe**."]}$kk$::jsonb, 21),
  ('reflexion', $kk${"question": "À quel moment de la journée avez-vous le plus de mal à répondre à un pleur avec calme ? Qu'est-ce qui vous aiderait : un relais, un mot en équipe, autre chose ?", "sous_titre": "Demander de l'aide fait partie du métier. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 22),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Une collègue à bout", "contexte": "11 h 30. Une collègue sort de la salle de repos, les traits tirés. Dans la section, un enfant pleure depuis un long moment.", "repliques": [{"qui": "Votre collègue", "texte": "Je n'en peux plus de ses pleurs. J'ai envie de le mettre à l'écart cinq minutes, le temps de souffler."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Merci de me le dire, c'est important. Le mettre à l'écart, ce serait le laisser seul avec une détresse qu'il ne peut pas apaiser : on ne le fait pas. Donne-le-moi, je reste avec lui, et toi tu souffles quelques minutes. On en parle ensemble à la prochaine réunion.", "points": ["Remercier : dire qu'on n'en peut plus, c'est ce qui évite la faute.", "Rappeler que l'isolement d'un enfant est exclu.", "Proposer un relais concret et immédiat.", "Renvoyer l'analyse à l'équipe, sans juger la collègue."]}$kk$::jsonb, 23),
  ('question', $kk${"enonce": "Parmi ces affirmations, lesquelles sont justes ? (plusieurs réponses)", "options": [{"texte": "Un pleur est un système d'alarme : l'enfant a besoin de l'adulte pour s'apaiser", "juste": true}, {"texte": "Un enfant pleure parfois pour manipuler l'adulte", "juste": false}, {"texte": "Les émotions d'un jeune enfant sont toujours vraies, même quand elles nous paraissent exagérées", "juste": true}, {"texte": "Laisser un enfant seul face à sa tempête l'aide à apprendre à se calmer", "juste": false}, {"texte": "Demander de l'aide quand on n'en peut plus fait partie du métier", "juste": true}], "explication": "Un pleur est un **signal**, pas une manipulation. Les émotions sont **toujours vraies**, et laisser un enfant seul au milieu de sa tempête est délétère, non formateur. Demander de l'aide, c'est ce qui permet de **continuer à bien accompagner**."}$kk$::jsonb, 24),
  ('retenir', $kk${"titre": "À retenir", "points": ["**Un pleur est un message :** un système d'alarme, ni une exagération ni une manipulation. On cherche ce qu'il dit avant de chercher à le faire cesser.", "**Le corps parle aussi :** gestuelle, regard, crispation, recul, retrait.", "**Port d'attache :** je réponds de façon chaleureuse, sans anticiper ni tarder, je console, je reste disponible.", "**On ne laisse pas un enfant seul au milieu de sa tempête :** on ne punit pas, on n'isole pas.", "**Boussole :** je nomme l'émotion, je la reconnais comme légitime, je soutiens l'enfant plutôt que de la faire cesser.", "**Prendre soin de ses propres émotions :** en parler, demander de l'aide quand on n'en peut plus, analyser en équipe."]}$kk$::jsonb, 25),
  ('essayer', $kk${"label": "À essayer après la séquence", "titre": "Un pleur, trois temps", "etapes": [{"titre": "Observer.", "texte": "Quand un enfant pleure, je note ce que je pense qu'il dit : fatigue, faim, besoin de lien, émotion trop grosse."}, {"titre": "Répondre.", "texte": "Je m'approche, je me mets à sa hauteur, je nomme ce que je vois : « Tu es triste, je comprends. Je suis là. »"}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce que j'ai observé, comme une observation à discuter."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$::jsonb, 26),
  ('discussion', $kk${"label": "Échange avec les autres participants", "titre": "Partagez un mot ou un geste", "consigne": "Quel mot ou quel geste vous aide à accompagner un enfant qui pleure ? Partagez-le en une ou deux phrases, sans nom d'enfant ni de collègue, puis lisez ce que proposent les autres participants : vous y trouverez peut-être une idée à tester."}$kk$::jsonb, 27),
  ('texte', $kk${"titre": "Pour aller plus loin", "paragraphes": ["Vous avez terminé la **première séquence du module 2**. Pour approfondir, la source citée dans le projet pédagogique : **Janusz Korczak**, « Le droit de l'enfant au respect » (1929, éditions Fabert, 2017), et « Quand je redeviendrai petit ». Pour le doudou : **Donald W. Winnicott**, qui l'a théorisé sous le nom d'objet transitionnel.", "Dans la séquence 2, vous verrez comment **poser un cadre sans punir ni isoler**."]}$kk$::jsonb, 28)
  ) as v(type, contenu, ordre);

  raise notice '33.2 : 29 blocs ajoutés';
end
$do$;
-- FIN 33.2

-- ---------------------------------------------------------------------------
-- 33c Contrôle (lecture seule). Attendu : séquence 1/3 avec 29 blocs (10 texte, 7 question, 3 dialogue, 3 reflexion, 1 citation, 1 comparaison, 1 discussion, 1 essayer, 1 retenir, 1 scenes),
-- publie = false, sans trame.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame is null) as sans_trame, m.ordre,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs,
       (select string_agg(x.type || ' ' || x.n, ', ' order by x.type)
          from (select b.type, count(*) as n from public.bloc b where b.module_id = m.id group by b.type) x) as repartition
from public.module m join public.theme t on t.id = m.theme_id
where t.nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$ order by m.ordre;
-- FIN 33c
